package com.pricetrack.exchange.custody.authorization;

import com.pricetrack.exchange.custody.runtime.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.sql.DataSource;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.Test;
import org.web3j.crypto.ECKeyPair;
import static com.pricetrack.exchange.custody.authorization.CConsentModelsTest.*;
import static org.junit.jupiter.api.Assertions.*;

/** Fresh H2 only; PostgreSQL triggers/roles/concurrency and JWT/RPC are NOT tested here. */
public class CConsentStoreTest {
    static class Time extends Clock {Instant value=NOW;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return value;}}
    record Fixture(DataSource ds,Time time,CConsentStore store){}
    static Fixture fixture(){
        var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:c_consent_"+UUID.randomUUID().toString().replace("-","")+";MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");
        try(Connection c=ds.getConnection();Statement s=c.createStatement()){
            s.execute("CREATE TABLE public.users(id BIGINT PRIMARY KEY); INSERT INTO public.users VALUES(1),(2),(3)");
            // Minimal read-only shape of existing wallet link; existing production schema is not changed.
            s.execute("CREATE SCHEMA tms_c_identity; CREATE TABLE tms_c_identity.wallet_links(deployment_id CHAR(64),user_id BIGINT REFERENCES public.users(id),wallet CHAR(42),PRIMARY KEY(deployment_id,user_id),UNIQUE(deployment_id,wallet))");
            try(var p=c.prepareStatement("INSERT INTO tms_c_identity.wallet_links VALUES(?,?,?)")){p.setString(1,identity().deploymentId());p.setLong(2,1);p.setString(3,OWNER);p.executeUpdate();p.setLong(2,2);p.setString(3,addr(99));p.executeUpdate();}
            try(var in=CConsentStoreTest.class.getResourceAsStream("/c-consent-schema.sql")){String sql=new String(Objects.requireNonNull(in).readAllBytes(),StandardCharsets.UTF_8);s.execute(sql.split("-- PostgreSQL append-only enforcement:",2)[0]);}
        }catch(Exception e){throw new AssertionError("H2_FIXTURE",e);}
        Time time=new Time();return new Fixture(ds,time,new CConsentStore(ds,identity(),time));
    }
    static int count(DataSource ds,String table){try(Connection c=ds.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT count(*) FROM tms_c_execution."+table)){r.next();return r.getInt(1);}catch(SQLException e){throw new AssertionError("H2_COUNT");}}
    @Test void draftAndConsentAreExactIdempotentHistoricalRecords(){var f=fixture();var i=intent();var d=f.store.createDraft(1,"request-123",i);assertEquals(d,f.store.createDraft(1,"request-123",i));var signed=f.store.acceptConsent(1,i.operationId(),d.intentDigest(),signature(i,KEY));f.time.value=NOW.plusSeconds(121);assertEquals(d,f.store.createDraft(1,"request-123",i));assertEquals(signed,f.store.acceptConsent(1,i.operationId(),d.intentDigest(),signature(i,KEY)));assertEquals(1,count(f.ds,"drafts"));assertEquals(1,count(f.ds,"consents"));assertEquals(CConsentModels.SCOPE,signed.scope());assertFalse(signed.toString().contains(signature(i,KEY)));}
    @Test void alteredRequestAndCrossUserFailClosed(){var f=fixture();var i=intent();var d=f.store.createDraft(1,"request-123",i);assertEquals("C_CONSENT_IDEMPOTENCY_CONFLICT",assertThrows(CCustodyFailure.class,()->f.store.createDraft(1,"request-123",change(i,"nonce",java.math.BigInteger.ONE))).code());assertEquals(404,assertThrows(CCustodyFailure.class,()->f.store.findDraft(2,i.operationId())).status());assertEquals(403,assertThrows(CCustodyFailure.class,()->f.store.createDraft(2,"request-456",i)).status());assertEquals(409,assertThrows(CCustodyFailure.class,()->f.store.createDraft(3,"request-789",i)).status());assertTrue(f.store.findByKey(2,"request-123").isEmpty());}
    @Test void unsignedWrongOwnerDomainAndDigestCannotRecordConsent(){var f=fixture();var i=intent();var d=f.store.createDraft(1,"request-123",i);var crypto=new com.pricetrack.exchange.custody.proof.CEip712Verifier();for(String bad:List.of("0x",signature(i,ECKeyPair.create(java.math.BigInteger.ONE)),signature(change(i,"nonce",java.math.BigInteger.ONE),KEY),signatureDigest(crypto.intentDigest(i,java.math.BigInteger.ONE,identity().controller().address()),KEY),signatureDigest(crypto.intentDigest(i,identity().chainId(),addr(88)),KEY)))assertEquals("C_CONSENT_INVALID_SIGNATURE",assertThrows(CCustodyFailure.class,()->f.store.acceptConsent(1,i.operationId(),d.intentDigest(),bad)).code());assertEquals("C_CONSENT_DIGEST_CONFLICT",assertThrows(CCustodyFailure.class,()->f.store.acceptConsent(1,i.operationId(),hash(99),signature(i,KEY))).code());assertEquals(0,count(f.ds,"consents"));}
    @Test void newExpiredConsentIsRejectedButReadRemainsAvailable(){var f=fixture();var i=intent();var d=f.store.createDraft(1,"request-123",i);f.time.value=NOW.plusSeconds(121);assertEquals(d,f.store.findByKey(1,"request-123").orElseThrow());assertEquals("C_CONSENT_INTENT_WINDOW",assertThrows(CCustodyFailure.class,()->f.store.acceptConsent(1,i.operationId(),d.intentDigest(),signature(i,KEY))).code());assertTrue(f.store.findConsent(1,i.operationId()).isEmpty());}
    @Test void differentValidSignatureCannotReplaceRecordedConsent(){var f=fixture();var i=intent();var d=f.store.createDraft(1,"request-123",i);var original=f.store.acceptConsent(1,i.operationId(),d.intentDigest(),signature(i,KEY));String alternative=alternateSignature(i);assertTrue(!alternative.equals(signature(i,KEY)),"trial signatures must differ");new com.pricetrack.exchange.custody.proof.CEip712Verifier().verifyIntent(i,identity().chainId(),identity().controller().address(),OWNER,alternative);assertEquals("C_CONSENT_IDEMPOTENCY_CONFLICT",assertThrows(CCustodyFailure.class,()->f.store.acceptConsent(1,i.operationId(),d.intentDigest(),alternative)).code());assertEquals(original,f.store.findConsent(1,i.operationId()).orElseThrow());}
    @Test void recordAndWindowUseOneCapturedClockInstant(){var f=fixture();var i=intent();var d=f.store.createDraft(1,"request-123",i);var reads=new java.util.concurrent.atomic.AtomicInteger();Clock sequence=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return NOW.plusSeconds(120+reads.getAndIncrement());}};var store=new CConsentStore(f.ds,identity(),sequence);var consent=store.acceptConsent(1,i.operationId(),d.intentDigest(),signature(i,KEY));assertEquals(NOW.plusSeconds(120),consent.recordedAt());assertEquals(1,reads.get());}
    @Test void failedInsertRollsBackWithoutAssetOrConsentCreation(){var f=fixture();var i=intent();var d=f.store.createDraft(1,"request-123",i);var guarded=new CConsentStore(fault(f.ds,"insert"),identity(),f.time);var e=assertThrows(CCustodyFailure.class,()->guarded.acceptConsent(1,i.operationId(),d.intentDigest(),signature(i,KEY)));assertEquals("C_CONSENT_STORAGE",e.code());assertNull(e.getCause());assertFalse(e.toString().contains("private"));assertEquals(0,count(f.ds,"consents"));assertEquals(1,count(f.ds,"drafts"));}
    @Test void commitUnknownAfterCommitIsObservedWithoutDuplicate(){var f=fixture();var guarded=new CConsentStore(fault(f.ds,"after"),identity(),f.time);assertEquals("C_CONSENT_COMMIT_UNKNOWN",assertThrows(CCustodyFailure.class,()->guarded.createDraft(1,"request-123",intent())).code());assertTrue(f.store.findByKey(1,"request-123").isPresent());assertEquals(1,count(f.ds,"drafts"));assertEquals(f.store.findByKey(1,"request-123").orElseThrow(),f.store.createDraft(1,"request-123",intent()));}
    @Test void commitUnknownBeforeCommitIsObservedAbsentWithoutAutomaticRetry(){var f=fixture();var guarded=new CConsentStore(fault(f.ds,"before"),identity(),f.time);assertEquals("C_CONSENT_COMMIT_UNKNOWN",assertThrows(CCustodyFailure.class,()->guarded.createDraft(1,"request-123",intent())).code());assertTrue(f.store.findByKey(1,"request-123").isEmpty());assertEquals(0,count(f.ds,"drafts"));}
    @Test void twoWorkersProduceOneImmutableDraftAndConsent()throws Exception{var f=fixture();var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{List<Future<CConsentModels.Consent>> tasks=new ArrayList<>();for(int n=0;n<2;n++)tasks.add(pool.submit(()->{start.await();var d=f.store.createDraft(1,"request-123",intent());return f.store.acceptConsent(1,intent().operationId(),d.intentDigest(),signature(intent(),KEY));}));start.countDown();assertEquals(tasks.get(0).get(8,TimeUnit.SECONDS),tasks.get(1).get(8,TimeUnit.SECONDS));assertEquals(1,count(f.ds,"drafts"));assertEquals(1,count(f.ds,"consents"));}finally{pool.shutdownNow();}}
    static DataSource fault(DataSource ds,String mode){var fired=new AtomicBoolean();return (DataSource)Proxy.newProxyInstance(DataSource.class.getClassLoader(),new Class<?>[]{DataSource.class},(p,m,a)->{Object v=invoke(m,ds,a);if(!m.getName().equals("getConnection"))return v;Connection c=(Connection)v;return Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class<?>[]{Connection.class},(p2,m2,a2)->{if(!mode.equals("insert")&&m2.getName().equals("commit")&&fired.compareAndSet(false,true)){if(mode.equals("after"))c.commit();throw new SQLException("private ambiguous detail","08006");}Object result=invoke(m2,c,a2);if(mode.equals("insert")&&m2.getName().equals("prepareStatement")&&a2[0].toString().contains("INSERT INTO tms_c_execution.consents")){PreparedStatement s=(PreparedStatement)result;return Proxy.newProxyInstance(PreparedStatement.class.getClassLoader(),new Class<?>[]{PreparedStatement.class},(p3,m3,a3)->{if(m3.getName().equals("executeUpdate")&&fired.compareAndSet(false,true))throw new SQLException("private injected detail","40001");return invoke(m3,s,a3);});}return result;});});}
    static Object invoke(Method m,Object target,Object[] args)throws Throwable{try{return m.invoke(target,args);}catch(InvocationTargetException e){throw e.getCause();}}
    public static void main(String[] args){if(args.length!=0)throw new IllegalArgumentException("C_CONSENT_TEST_SCOPE");var request=org.junit.platform.launcher.core.LauncherDiscoveryRequestBuilder.request().selectors(org.junit.platform.engine.discovery.DiscoverySelectors.selectClass(CConsentModelsTest.class),org.junit.platform.engine.discovery.DiscoverySelectors.selectClass(CConsentStoreTest.class)).build();var listener=new org.junit.platform.launcher.listeners.SummaryGeneratingListener();org.junit.platform.launcher.core.LauncherFactory.create().execute(request,listener);var s=listener.getSummary();var out=new java.io.PrintWriter(System.out,true);s.printTo(out);s.printFailuresTo(out);System.exit(s.getTestsFoundCount()==14&&s.getTestsSucceededCount()==14&&s.getTotalFailureCount()==0&&s.getTestsSkippedCount()==0&&s.getTestsAbortedCount()==0?0:1);}
}
